"use strict";
import { Stack, styled } from "@tamagui/core";
import { createSwitch } from "@tamagui/switch";
const Frame = styled(Stack, {
  width: 40,
  height: 20,
  borderRadius: 20,
  borderWidth: 0,
  cursor: "pointer",
  padding: "10px 0",
  variants: {
    checked: {
      true: {
        backgroundColor: "$absGreen"
      },
      false: {
        backgroundColor: "$accent2"
      }
    }
  },
  defaultVariants: {
    checked: false
  }
});
const Thumb = styled(Stack, {
  width: 18,
  height: 18,
  backgroundColor: "$neutral1",
  borderRadius: 18
});
export const Switch = createSwitch({
  Frame,
  Thumb
});
export default function AutoSwitch({ checked, onCheckedChange, disabled }) {
  return <Switch checked={checked} onCheckedChange={disabled ? void 0 : onCheckedChange} disabled={disabled}>
      <Switch.Thumb animation="quicker" />
    </Switch>;
}
