"use strict";
import { useVeABXLock } from "hooks/useVeABXLocks";
import { useCallback, useMemo } from "react";
import { Flex, Text } from "ui/src";
import { Orbit } from "ui/src/components/icons";
import { MAX_LOCK_DURATION_SECONDS, secondsToDays } from "utils/lockCalculations";
import { useModifyLockContext } from "../ModifyLockContextProvider";
import AutoSwitch from "./AutoSwitch";
import RangeInput from "./Range";
export default function Extend() {
  const { selectedLockId, formData, updateFormData } = useModifyLockContext();
  const { data: currentLock } = useVeABXLock(selectedLockId || void 0);
  const { remainingDays, maxExtensionDays, maxLockDays, isAlreadyPermanent } = useMemo(() => {
    const currentTimeSeconds = Math.floor(Date.now() / 1e3);
    const currentUnlockTime = currentLock ? parseInt(currentLock.lockEnd) : currentTimeSeconds;
    const remaining = Math.max(0, secondsToDays(currentUnlockTime - currentTimeSeconds));
    const maxDays = secondsToDays(MAX_LOCK_DURATION_SECONDS);
    const maxExtension = maxDays - remaining;
    const isPermanent = currentLock?.permanent || false;
    return {
      remainingDays: remaining,
      maxLockDays: maxDays,
      maxExtensionDays: maxExtension,
      isAlreadyPermanent: isPermanent
    };
  }, [currentLock]);
  const handlePermanentLockToggle = useCallback(
    (checked) => {
      updateFormData({
        extendToMaxLock: checked,
        extendDays: 0
        // Permanent lock doesn't need extension days
      });
    },
    [updateFormData]
  );
  return <Flex mt={"$gap36"}>
      <Flex borderWidth={1} borderColor={"$surface3"} borderRadius={"$rounded12"} p={"$padding12"}>
        <Flex row gap={"$gap12"} alignItems="center">
          <AutoSwitch
    checked={isAlreadyPermanent || formData.extendToMaxLock}
    onCheckedChange={handlePermanentLockToggle}
    disabled={isAlreadyPermanent}
  />
          <Text variant="buttonLabel3">Permanent Lock Mode</Text>
          <Orbit size={20} color="$neutral3" />
        </Flex>

        <Text variant="body4" mt={"$gap12"}>
          {isAlreadyPermanent ? "This lock is already permanent and has maximum 1-to-1 voting power." : "When activated, converts this lock to a permanent lock with maximum 1-to-1 voting power. Permanent locks never expire and don't need to be extended."}
        </Text>

        {isAlreadyPermanent && <Text variant="body4" mt={"$gap12"} color="$accent1">
            ✓ Lock is already permanent
          </Text>}
      </Flex>

      {!isAlreadyPermanent && !formData.extendToMaxLock && maxExtensionDays > 0 && <RangeInput
    value={formData.extendDays}
    onChange={(days) => updateFormData({ extendDays: days })}
    min={0}
    max={maxExtensionDays}
    label={`Extend by ${formData.extendDays} days`}
  />}

      {!isAlreadyPermanent && formData.extendToMaxLock && <Flex mt={"$gap24"} p={"$padding12"} borderWidth={1} borderColor={"$accent1"} borderRadius={"$rounded12"}>
          <Text variant="body3" color="$accent1">
            Will convert to permanent lock with maximum voting power (1:1 ratio)
          </Text>
        </Flex>}

      {!isAlreadyPermanent && maxExtensionDays <= 0 && !formData.extendToMaxLock && <Flex mt={"$gap24"} p={"$padding12"} borderWidth={1} borderColor={"$neutral3"} borderRadius={"$rounded12"}>
          <Text variant="body3" color="$neutral2">
            This lock is already at maximum duration. You can convert it to a permanent lock for maximum voting power.
          </Text>
        </Flex>}
    </Flex>;
}
