"use strict";
import { useLockContract } from "hooks/useLockContract";
import AmoutInput from "pages/Locks/common/AmoutInput";
import AvailableAmoutAndBalancePercentage from "pages/Locks/common/AvailableAmoutAndBalancePercentage";
import { Flex, Text } from "ui/src";
import { parseLockAmount } from "utils/lockCalculations";
import { useAccount } from "wagmi";
import { useModifyLockContext } from "../ModifyLockContextProvider";
export default function Increase() {
  const { address: account } = useAccount();
  const { getFormattedABXBalance, needsApproval, isWritePending } = useLockContract();
  const { formData, updateFormData } = useModifyLockContext();
  const amount = formData.increaseAmount;
  const userBalance = getFormattedABXBalance();
  const handlePercentageSelect = (percentage) => {
    const userBalanceNum = parseFloat(userBalance);
    if (userBalanceNum > 0) {
      const calculatedAmount = (userBalanceNum * percentage / 100).toString();
      updateFormData({ increaseAmount: calculatedAmount });
    }
  };
  const handleAmountChange = (newAmount) => {
    updateFormData({ increaseAmount: newAmount });
  };
  const amountValidation = parseLockAmount(amount);
  const hasError = !amountValidation.isValid;
  const errorMessage = amountValidation.error;
  let finalError = errorMessage;
  if (amountValidation.isValid && amount) {
    const userBalanceNum = parseFloat(userBalance);
    const requestedAmount = parseFloat(amount);
    if (requestedAmount > userBalanceNum) {
      finalError = "Insufficient ABX balance";
    }
  }
  return <Flex mt={"$gap36"}>
      <AvailableAmoutAndBalancePercentage
    title="Add to lock"
    onPercentageSelect={handlePercentageSelect}
  />
      <Flex mt={"$gap12"}>
        <AmoutInput
    value={amount}
    onValueChange={handleAmountChange}
    error={finalError}
    userBalance={userBalance}
  />
      </Flex>
      
      {account && amount && !hasError && <Flex mt={"$gap12"} p={"$spacing12"} backgroundColor={"$surface3"} borderRadius={"$rounded8"}>
          <Text variant="body4" color={"$neutral2"}>
            {needsApproval(amount) ? `Approval required for ${amount} ABX` : `Ready to increase lock by ${amount} ABX`}
          </Text>
        </Flex>}
    </Flex>;
}
